'use strict';
let vaultKey=null,vaultSalt=null,vaultRevision=0,vaultExists=null,vaultDirty=false,vaultError='',vaultStatus='Checking private storage…',vaultTimer=null,vaultQueue=Promise.resolve(),vaultGeneration=0;
let activeLogId=crypto.randomUUID();
state.chatLogs=Array.isArray(state.chatLogs)?state.chatLogs:[];
state.preferences={country:'',journalMemory:false,...state.preferences};
const to64=bytes=>{let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s);};
const from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function auraLocalAPI(path,body,retry=true){if(!chatConfig){const r=await fetch('/api/config');if(!r.ok)throw Error('Aura’s local server is unavailable.');chatConfig=await r.json();}const r=await fetch(path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json','X-Aura-Token':chatConfig.token},...(body?{body:JSON.stringify(body)}:{})});if(r.status===403&&retry){chatConfig=null;return auraLocalAPI(path,body,false);}const data=await r.json();if(!r.ok)throw Error(data.error||'The local request failed.');return data;}
async function deriveVaultKey(passphrase,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(passphrase),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',hash:'SHA-256',salt,iterations:600000},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);}
async function encryptAuraSnapshot(snapshot,key,salt){const iv=crypto.getRandomValues(new Uint8Array(12)),plain=new TextEncoder().encode(JSON.stringify(snapshot)),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain);return {version:1,kdf:'PBKDF2-SHA256',iterations:600000,salt:to64(salt),iv:to64(iv),data:to64(new Uint8Array(cipher))};}
async function decryptAuraSnapshot(record,key){if(record.version!==1||record.kdf!=='PBKDF2-SHA256'||record.iterations!==600000)throw Error('Unsupported encrypted vault.');const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:from64(record.iv)},key,from64(record.data));const snapshot=JSON.parse(new TextDecoder().decode(plain));if(!snapshot.state||!['entries','moods','sessions','plans','chatLogs'].every(k=>Array.isArray(snapshot.state[k]))||!Array.isArray(snapshot.chatMessages))throw Error('Invalid vault data.');return snapshot;}
function updateVaultStatus(message){vaultStatus=message;document.querySelectorAll('.vault-status').forEach(x=>x.textContent=message);}
function syncAuraLog(){if(!chatMessages.length)return;const existing=state.chatLogs.find(x=>x.id===activeLogId);const log={id:activeLogId,created:existing?.created||stamp(),updated:stamp(),title:(chatMessages.find(x=>x.role==='user')?.text||'Conversation').slice(0,100),messages:chatMessages.map(x=>({role:x.role,text:x.text}))};if(existing)Object.assign(existing,log);else state.chatLogs.push(log);}
function auraSnapshot(){syncAuraLog();return JSON.parse(JSON.stringify({state:{...state,persist:false},activeLogId,chatMessages}));}
function queueVaultWrite(){vaultQueue=vaultQueue.then(async()=>{if(!vaultKey||!vaultDirty)return;const generation=vaultGeneration,snapshot=auraSnapshot(),key=vaultKey,salt=vaultSalt;updateVaultStatus('Saving encrypted data…');const record=await encryptAuraSnapshot(snapshot,key,salt);const result=await auraLocalAPI('/api/vault',{expectedRevision:vaultRevision,vault:record});vaultRevision=result.revision;vaultExists=true;vaultError='';if(generation===vaultGeneration)vaultDirty=false;try{localStorage.removeItem(KEY);}catch{}updateVaultStatus(vaultDirty?'Changes waiting to save…':'Encrypted · saved on this computer');}).catch(error=>{vaultError=error.message;updateVaultStatus('Not saved · '+error.message);toast('Vault not saved. Open Logs for details.');});return vaultQueue;}
window.auraPersist=function(){syncAuraLog();if(!vaultKey){updateVaultStatus(vaultExists?'Vault locked · this tab only':'This tab only · set up private logs to keep it');return;}vaultDirty=true;vaultGeneration++;updateVaultStatus('Saving…');clearTimeout(vaultTimer);vaultTimer=setTimeout(queueVaultWrite,600);};
async function flushAuraVault(){clearTimeout(vaultTimer);await queueVaultWrite();if(vaultError)throw Error(vaultError);}
async function checkAuraVault(){try{const data=await auraLocalAPI('/api/vault');vaultExists=data.exists;updateVaultStatus(vaultKey?'Encrypted · unlocked':data.exists?'Vault locked · unlock to restore your space':'This tab only · set up private logs to keep it');if(location.hash==='#logs'&&!$('#vault-passphrase')?.value)route();}catch(e){updateVaultStatus('Private storage unavailable · '+e.message);}}
async function openAuraVault(passphrase,confirmation){const data=await auraLocalAPI('/api/vault');vaultExists=data.exists;let key,salt;
 if(data.exists){salt=from64(data.vault.salt);key=await deriveVaultKey(passphrase,salt);let snapshot;try{snapshot=await decryptAuraSnapshot(data.vault,key);}catch{throw Error('Could not unlock. Check the passphrase; if correct, the vault file may be damaged. Nothing was changed.');}const transient=state,transientChat=chatMessages.slice();syncAuraLog();state=snapshot.state;state.weekly=Array.isArray(state.weekly)?state.weekly:[];state.sessionReviews=Array.isArray(state.sessionReviews)?state.sessionReviews:[];state.memoryUsage={...state.memoryUsage,...transient.memoryUsage};state.persist=false;state.preferences={country:'',journalMemory:false,...state.preferences};for(const field of ['entries','moods','sessions','plans','chatLogs','weekly','sessionReviews']){const recordKey=x=>field==='weekly'?x.week:x.id||x.date;const merged=new Map(state[field].map(x=>[recordKey(x),x]));for(const x of transient[field]||[])if(!merged.has(recordKey(x)))merged.set(recordKey(x),x);state[field]=Array.from(merged.values());}if(transientChat.length){chatMessages=transientChat;}else{chatMessages=snapshot.chatMessages;activeLogId=snapshot.activeLogId||crypto.randomUUID();}vaultRevision=data.vault.revision;
 }else{if(passphrase.length<12)throw Error('Use a passphrase of at least 12 characters.');if(passphrase!==confirmation)throw Error('The passphrases do not match.');salt=crypto.getRandomValues(new Uint8Array(16));key=await deriveVaultKey(passphrase,salt);vaultRevision=0;}
 vaultKey=key;vaultSalt=salt;vaultError='';window.auraPersist();await flushAuraVault();route();toast('Your private space is unlocked.');}
async function lockAuraVault(discard=false){if(chatBusy)throw Error('Wait for Aura’s reply before locking.');if(!discard)await flushAuraVault();else{clearTimeout(vaultTimer);await vaultQueue;}vaultKey=null;vaultSalt=null;vaultDirty=false;vaultError='';chatMessages=[];chatDraft='';chatError='';flow=null;selectedMood=0;if(window.auraClearTransient)window.auraClearTransient();activeLogId=crypto.randomUUID();chatConsent=false;state={moods:[],entries:[],sessions:[],plans:[],chatLogs:[],preferences:{country:'',journalMemory:false},persist:false,onboarded:true};updateVaultStatus('Vault locked');route();}
window.addEventListener('pagehide',()=>{if(vaultKey&&vaultDirty)updateVaultStatus('Closing before saving may lose recent changes.');});
window.addEventListener('beforeunload',e=>{if(vaultKey&&vaultDirty){e.preventDefault();e.returnValue='';}});
checkAuraVault();
